 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(pos) });
+      break;
+    }
+    if (open > pos) {
+      tokens.push({ kind: "text", text: template.slice(pos, open) });
+    }
+
+    const raw = template.startsWith("{{{", open);
+    const closer = raw ? "}}}" : "}}";
+    const innerStart = open + (raw ? 3 : 2);
+    const close = template.indexOf(closer, innerStart);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+
+    const inner = template.slice(innerStart, close).trim();
+    tokens.push(tagToken(inner, raw));
+    pos = close + closer.length;
+  }
+
+  return tokens;
 }
+
+function tagToken(inner: string, raw: boolean): Token {
+  if (raw) {
+    return { kind: "value", expr: inner, raw: true };
+  }
+  if (inner === "else") {
+    return { kind: "else" };
+  }
+  if (inner === "/if") {
+    return { kind: "end" };
+  }
+  const ifMatch = /^#if(?:\s+(.*))?$/s.exec(inner);
+  if (ifMatch) {
+    return { kind: "if", path: (ifMatch[1] ?? "").trim() };
+  }
+  return { kind: "value", expr: inner, raw: false };
+}
